command:
// Open Legend Unofficial — Asset Browser
// A 6-tab browser (Banes, Boons, Feats, Perks, Flaws, Items) over the system's
// compendium packs, each tab with its own domain filters. Every row is clickable
// (opens the entry's sheet) and draggable (drop onto an actor sheet or the canvas).
// Built as a plain ApplicationV2 with string rendering — no template files needed,
// so it ships entirely inside this macro.
const { ApplicationV2 } = foundry.applications.api;
const esc = s => foundry.utils.escapeHTML?.(String(s ?? "")) ?? String(s ?? "");
const SYS = game.system.id;

function pack(name, label) {
  return game.packs.get(`${SYS}.${name}`)
    ?? game.packs.find(p => p.metadata?.name === name)
    ?? (label ? game.packs.find(p => p.metadata?.label === label) : null);
}
const PACKS = {
  banes: pack("banes"), boons: pack("boons"), feats: pack("feats"),
  perks: pack("perks"), flaws: pack("flaws"),
  weapons: pack("weapons"), armor: pack("armor"), gear: pack("gear"),
  extraordinary: pack("extraordinary-items", "Extraordinary Items")
};

// Human labels for extraordinary property keys (mirrors OPENLEGEND.itemProperties).
const PROP_LABELS = {
  area: "Area", damageType: "Damage (type)", deadly: "Deadly", powerful: "Powerful",
  augmenting: "Augmenting", autonomous: "Autonomous", consumable: "Consumable",
  expendable: "Expendable", potent: "Potent", cursed: "Cursed", baneful: "Baneful",
  persistent: "Persistent", reliable: "Reliable", sentient: "Sentient", special: "Special",
  limiting: "Limiting", intelligent: "Intelligent"
};
const propLabel = k => PROP_LABELS[k] ?? k;
const xtraProps = d => uniqSorted((d.system?.extraordinaryProperties ?? []).map(p => p.name));
const xtraAttrs = d => uniqSorted((d.system?.extraordinaryAttributes ?? []).map(a => a.key));
const xtraBanes = d => uniqSorted((d.system?.extraordinaryBanes ?? []).map(b => b.name));
const xtraBoons = d => uniqSorted((d.system?.extraordinaryBoons ?? []).map(b => b.name));
const cap = s => String(s ?? "").replace(/^\w/, c => c.toUpperCase());

const uniqSorted = arr => [...new Set(arr.filter(v => v !== "" && v != null))]
  .sort((a, b) => (typeof a === "number" && typeof b === "number")
    ? a - b : String(a).localeCompare(String(b)));

const baneAttrs = d => uniqSorted((d.system?.attacks ?? []).map(a => a.attackingAttribute));
const baneDefs  = d => uniqSorted((d.system?.attacks ?? []).map(a => a.defense));
const boonAttrs = d => uniqSorted(d.system?.attributes ?? []);
const docTags   = d => (d.system?.tags ?? []);
const featCost  = d => { const c = d.system?.cost; return Array.isArray(c) ? Number(c[0] ?? 0) : Number(c ?? 0); };
const wealthOf  = d => d.system?.wealthLevel;

class AssetBrowser extends ApplicationV2 {
  static DEFAULT_OPTIONS = {
    id: "ol-asset-browser",
    classes: ["openlegend", "ol-asset-browser"],
    window: { title: "Open Legend — Asset Browser", icon: "fas fa-book-open", resizable: true },
    position: { width: 740, height: 760 },
    actions: {}
  };

  data = {};   // { banes:[], boons:[], ... } full documents
  tab = "banes";
  filters = {
    banes: { q: "", pl: "", attr: "", def: "", tag: "" },
    boons: { q: "", pl: "", attr: "", tag: "" },
    feats: { q: "", tag: "", cost: "" },
    perks: { q: "" },
    flaws: { q: "" },
    items: { q: "", kind: "weapons", wealth: "", tag: "" },
    extraordinary: { q: "", type: "", wealth: "", prop: "", attr: "", bane: "", boon: "" }
  };

  static TABS = [
    { id: "banes", label: "Banes", icon: "fas fa-skull" },
    { id: "boons", label: "Boons", icon: "fas fa-hands-holding" },
    { id: "feats", label: "Feats", icon: "fas fa-star" },
    { id: "perks", label: "Perks", icon: "fas fa-thumbs-up" },
    { id: "flaws", label: "Flaws", icon: "fas fa-thumbs-down" },
    { id: "items", label: "Items", icon: "fas fa-box-open" },
    { id: "extraordinary", label: "Extraordinary", icon: "fas fa-wand-sparkles" }
  ];

  /* ApplicationV2 string-render hooks. */
  async _renderHTML() { return this.#html(); }
  _replaceHTML(result, content) { content.innerHTML = result; this.#activateListeners(content); }

  /* ---- rendering ------------------------------------------------------- */

  #selectField(key, label, options, value) {
    const opts = ['<option value="">Any</option>']
      .concat(options.map(o => `<option value="${esc(o)}" ${String(o) === String(value) ? "selected" : ""}>${esc(o)}</option>`))
      .join("");
    return `<label class="ol-ab-field"><span>${esc(label)}</span><select data-filter="${key}">${opts}</select></label>`;
  }

  #html() {
    const tabs = AssetBrowser.TABS.map(t =>
      `<a class="ol-ab-tab ${t.id === this.tab ? "active" : ""}" data-tab-id="${t.id}"><i class="${t.icon}"></i> ${t.label}</a>`
    ).join("");

    const { rows, total, filtersHtml, missing } = this.#tab();
    const missingMsg = (this.tab === "extraordinary")
      ? `The "Extraordinary Items" compendium isn't loaded. It was just added to the system — <strong>fully restart Foundry</strong> (return to setup and relaunch the world) so it registers; a browser refresh isn't enough.`
      : `No compendium exists for this type.`;
    const list = missing
      ? `<p class="ol-ab-empty">${missingMsg}</p>`
      : rows.length
        ? rows.map(r =>
            `<div class="ol-ab-row" data-uuid="${esc(r.uuid)}" draggable="true" title="Click to open · drag onto an actor or the canvas">
               <img src="${esc(r.img)}" width="28" height="28"/>
               <a class="ol-ab-name">${esc(r.name)}</a>
               ${r.meta ? `<span class="ol-ab-meta">${esc(r.meta)}</span>` : ""}
             </div>`).join("")
        : `<p class="ol-ab-empty">Nothing matches these filters.</p>`;

    return `
      <nav class="ol-ab-tabs">${tabs}</nav>
      <div class="ol-ab-filters">
        <input type="search" class="ol-ab-search" data-filter="q" value="${esc(this.filters[this.tab].q)}" placeholder="Search by name…"/>
        ${filtersHtml}
        <a class="ol-ab-clear" data-clear title="Clear filters"><i class="fas fa-filter-circle-xmark"></i></a>
      </div>
      <div class="ol-ab-count">${rows.length} of ${total} shown</div>
      <div class="ol-ab-list">${list}</div>`;
  }

  /** Filtered rows + the filter-bar HTML for the active tab. */
  #tab() {
    const f = this.filters[this.tab];
    const q = (f.q ?? "").trim().toLowerCase();
    const match = name => !q || String(name).toLowerCase().includes(q);
    const row = (d, meta) => ({ uuid: d.uuid, name: d.name, img: d.img, meta });
    const sel = this.#selectField.bind(this);

    if ( this.tab === "banes" ) {
      const all = this.data.banes;
      const rows = all.filter(d => match(d.name)
        && (f.pl === "" || Number(d.system?.powerLevel) === Number(f.pl))
        && (f.attr === "" || baneAttrs(d).includes(f.attr))
        && (f.def === "" || baneDefs(d).includes(f.def))
        && (f.tag === "" || docTags(d).includes(f.tag)))
        .map(d => row(d, `PL ${d.system?.powerLevel ?? "—"} · ${baneDefs(d).join("/") || "—"}`));
      const filtersHtml =
        sel("pl", "Power Level", uniqSorted(all.map(d => d.system?.powerLevel)), f.pl)
        + sel("attr", "Attacking Attr.", uniqSorted(all.flatMap(baneAttrs)), f.attr)
        + sel("def", "Defense", uniqSorted(all.flatMap(baneDefs)), f.def)
        + sel("tag", "Tag", uniqSorted(all.flatMap(docTags)), f.tag);
      return { rows: this.#sort(rows), total: all.length, filtersHtml };
    }
    if ( this.tab === "boons" ) {
      const all = this.data.boons;
      const rows = all.filter(d => match(d.name)
        && (f.pl === "" || Number(d.system?.powerLevel) === Number(f.pl))
        && (f.attr === "" || boonAttrs(d).includes(f.attr))
        && (f.tag === "" || docTags(d).includes(f.tag)))
        .map(d => row(d, `PL ${d.system?.powerLevel ?? "—"} · ${boonAttrs(d).join("/") || "—"}`));
      const filtersHtml =
        sel("pl", "Power Level", uniqSorted(all.map(d => d.system?.powerLevel)), f.pl)
        + sel("attr", "Invoking Attr.", uniqSorted(all.flatMap(boonAttrs)), f.attr)
        + sel("tag", "Tag", uniqSorted(all.flatMap(docTags)), f.tag);
      return { rows: this.#sort(rows), total: all.length, filtersHtml };
    }
    if ( this.tab === "feats" ) {
      const all = this.data.feats;
      const rows = all.filter(d => match(d.name)
        && (f.tag === "" || docTags(d).includes(f.tag))
        && (f.cost === "" || featCost(d) === Number(f.cost)))
        .map(d => row(d, `Cost ${featCost(d) || "—"}`));
      const filtersHtml =
        sel("tag", "Tag", uniqSorted(all.flatMap(docTags)), f.tag)
        + sel("cost", "Cost", uniqSorted(all.map(featCost)), f.cost);
      return { rows: this.#sort(rows), total: all.length, filtersHtml };
    }
    if ( (this.tab === "perks") || (this.tab === "flaws") ) {
      const all = this.data[this.tab];
      const rows = all.filter(d => match(d.name)).map(d => row(d, ""));
      return { rows: this.#sort(rows), total: all.length, filtersHtml: "" };
    }
    if ( this.tab === "extraordinary" ) {
      const all = this.data.extraordinary ?? [];
      const rows = all.filter(d => match(d.name)
        && (f.type === "" || d.type === f.type)
        && (f.wealth === "" || Number(wealthOf(d)) === Number(f.wealth))
        && (f.prop === "" || xtraProps(d).includes(f.prop))
        && (f.attr === "" || xtraAttrs(d).includes(f.attr))
        && (f.bane === "" || xtraBanes(d).includes(f.bane))
        && (f.boon === "" || xtraBoons(d).includes(f.boon)))
        .map(d => {
          const bits = [cap(d.type), `W${wealthOf(d) ?? "—"}`];
          const ps = xtraProps(d).map(propLabel);
          if ( ps.length ) bits.push(ps.join("/"));
          return row(d, bits.join(" · "));
        });
      const typeSel = `<label class="ol-ab-field"><span>Type</span><select data-filter="type">
          <option value="" ${f.type === "" ? "selected" : ""}>Any</option>
          <option value="weapon" ${f.type === "weapon" ? "selected" : ""}>Weapon</option>
          <option value="armor" ${f.type === "armor" ? "selected" : ""}>Armor</option>
          <option value="gear" ${f.type === "gear" ? "selected" : ""}>Gear</option>
        </select></label>`;
      // Property options: key→label pairs (value is the key, shown label is humanized).
      const propOpts = uniqSorted(all.flatMap(xtraProps));
      const propSelHtml = `<label class="ol-ab-field"><span>Property</span><select data-filter="prop">`
        + ['<option value="">Any</option>']
            .concat(propOpts.map(k => `<option value="${esc(k)}" ${k === f.prop ? "selected" : ""}>${esc(propLabel(k))}</option>`))
            .join("")
        + `</select></label>`;
      // Attribute options: value is the lowercase key, label is capitalized.
      const attrOpts = uniqSorted(all.flatMap(xtraAttrs));
      const attrSelHtml = `<label class="ol-ab-field"><span>Attribute</span><select data-filter="attr">`
        + ['<option value="">Any</option>']
            .concat(attrOpts.map(k => `<option value="${esc(k)}" ${k === f.attr ? "selected" : ""}>${esc(cap(k))}</option>`))
            .join("")
        + `</select></label>`;
      const filtersHtml = typeSel
        + sel("wealth", "Wealth Level", uniqSorted(all.map(wealthOf)), f.wealth)
        + propSelHtml
        + attrSelHtml
        + sel("bane", "Bane", uniqSorted(all.flatMap(xtraBanes)), f.bane)
        + sel("boon", "Boon", uniqSorted(all.flatMap(xtraBoons)), f.boon);
      return { rows: this.#sort(rows), total: all.length, filtersHtml, missing: !PACKS.extraordinary };
    }
    // items
    const all = this.data[f.kind] ?? [];
    const rows = all.filter(d => match(d.name)
      && (f.wealth === "" || Number(wealthOf(d)) === Number(f.wealth))
      && (f.tag === "" || docTags(d).includes(f.tag)))
      .map(d => row(d, `Wealth ${wealthOf(d) ?? "—"}`));
    const hasTags = all.some(d => docTags(d).length > 0);
    const kindSel = `<label class="ol-ab-field"><span>Type</span><select data-filter="kind">
        <option value="weapons" ${f.kind === "weapons" ? "selected" : ""}>Weapons</option>
        <option value="armor" ${f.kind === "armor" ? "selected" : ""}>Armor</option>
        <option value="gear" ${f.kind === "gear" ? "selected" : ""}>Gear</option>
      </select></label>`;
    const filtersHtml = kindSel
      + sel("wealth", "Wealth Level", uniqSorted(all.map(wealthOf)), f.wealth)
      + (hasTags ? sel("tag", "Tag", uniqSorted(all.flatMap(docTags)), f.tag) : "");
    return { rows: this.#sort(rows), total: all.length, filtersHtml, missing: !PACKS[f.kind] };
  }

  #sort(rows) { return rows.sort((a, b) => a.name.localeCompare(b.name)); }

  /* ---- listeners ------------------------------------------------------- */

  #activateListeners(root) {
    for ( const el of root.querySelectorAll("[data-tab-id]") ) {
      el.addEventListener("click", ev => { ev.preventDefault(); this.tab = el.dataset.tabId; this.render(); });
    }
    let t = null;
    for ( const el of root.querySelectorAll("[data-filter]") ) {
      const evt = (el.tagName === "SELECT") ? "change" : "input";
      el.addEventListener(evt, () => {
        const key = el.dataset.filter;
        this.filters[this.tab][key] = el.value;
        if ( (this.tab === "items") && (key === "kind") ) { this.filters.items.wealth = ""; this.filters.items.tag = ""; }
        if ( evt === "input" ) { clearTimeout(t); t = setTimeout(() => this.render(), 180); }
        else this.render();
      });
    }
    root.querySelector("[data-clear]")?.addEventListener("click", ev => {
      ev.preventDefault();
      const keep = (this.tab === "items") ? { kind: this.filters.items.kind } : {};
      for ( const k of Object.keys(this.filters[this.tab]) ) this.filters[this.tab][k] = keep[k] ?? "";
      this.render();
    });
    for ( const el of root.querySelectorAll(".ol-ab-row") ) {
      el.querySelector(".ol-ab-name")?.addEventListener("click", async ev => {
        ev.preventDefault();
        const doc = await fromUuid(el.dataset.uuid);
        doc?.sheet?.render(true);
      });
      el.addEventListener("dragstart", ev => {
        ev.dataTransfer.setData("text/plain", JSON.stringify({ type: "Item", uuid: el.dataset.uuid }));
        ev.dataTransfer.effectAllowed = "copy";
      });
    }
  }
}

/* ---- one-time CSS ------------------------------------------------------ */
const STYLE_ID = "ol-asset-browser-style";
if ( !document.getElementById(STYLE_ID) ) {
  const style = document.createElement("style");
  style.id = STYLE_ID;
  style.textContent = `
    .ol-asset-browser .window-content { display:flex; flex-direction:column; gap:8px; padding:8px; overflow:hidden; }
    .ol-ab-tabs { display:flex; flex-wrap:wrap; gap:4px; border-bottom:2px solid var(--ol-gold,#b8973a); padding-bottom:6px; }
    .ol-ab-tab { padding:4px 10px; border-radius:6px 6px 0 0; cursor:pointer; font-weight:600; color:#666; }
    .ol-ab-tab.active { background:var(--ol-purple,#4a2c6f); color:#fff; }
    .ol-ab-tab:hover { text-shadow:0 0 6px rgba(184,151,58,.6); }
    .ol-ab-filters { display:flex; flex-wrap:wrap; align-items:flex-end; gap:8px; }
    .ol-ab-field { display:flex; flex-direction:column; gap:2px; font-size:11px; }
    .ol-ab-field > span { font-weight:700; text-transform:uppercase; letter-spacing:.5px; color:#666; }
    .ol-ab-field select { min-width:108px; }
    .ol-ab-search { flex:1 1 160px; min-width:140px; }
    .ol-ab-clear { align-self:center; cursor:pointer; color:#8a2526; font-size:16px; }
    .ol-ab-count { font-size:11px; color:#777; }
    .ol-ab-list { flex:1 1 auto; overflow-y:auto; display:flex; flex-direction:column; gap:2px; }
    .ol-ab-row { display:flex; align-items:center; gap:8px; padding:3px 6px; border:1px solid transparent; border-radius:5px; cursor:grab; }
    .ol-ab-row:hover { background:rgba(74,44,111,.08); border-color:var(--ol-gold,#b8973a); }
    .ol-ab-row img { border:none; border-radius:4px; flex:0 0 auto; }
    .ol-ab-name { flex:1 1 auto; font-weight:600; cursor:pointer; }
    .ol-ab-meta { font-size:11px; color:#777; white-space:nowrap; }
    .ol-ab-empty { color:#999; font-style:italic; padding:12px; text-align:center; }
  `;
  document.head.appendChild(style);
}

/* ---- launch ------------------------------------------------------------ */
const app = new AssetBrowser();
const load = async () => {
  const out = {};
  for ( const [key, p] of Object.entries(PACKS) ) out[key] = p ? await p.getDocuments() : [];
  return out;
};
app.data = await load();
app.render(true);
